function Counter() {
  const [count, setCount] = useState(0);

  function handleClick() {
    setCount(count + 1);
    setCount(count + 1);
  }

  return <button onClick={handleClick}>{count}</button>;
}

function List() {
  const [items, setItems] = useState(['a']);

  function add() {
    items.push('b');
    setItems(items);
  }

  return <p onClick={add}>{items.join(', ')}</p>;
}
